"""Robust audio loading, validation, info and playback helpers.

Operating modes are carried with every clip so the UI never mixes them up:
    "uploaded"    - WAV the user uploaded
    "downloaded"  - public-dataset file stored under data/samples/ (see audio/datasets.py)
    "synthetic"   - generated by this program (audio/synth.py) - NOT measured ocean data
    "recorded"    - captured from a local input device (airborne microphone, NOT a hydrophone)

Amplitudes are digital full-scale values (-1..1). They are NOT calibrated acoustic pressure
unless the recording's own documentation provides a hydrophone sensitivity.
"""
from __future__ import annotations
import io
from dataclasses import dataclass, field
import numpy as np
from scipy.io import wavfile
from scipy.signal import resample_poly

MODES = ("uploaded", "downloaded", "synthetic", "recorded")
FS_MIN, FS_MAX = 100, 2_000_000
MIN_SAMPLES = 64


class AudioError(ValueError):
    """Raised with a message that tells the user what to fix."""


@dataclass
class AudioClip:
    samples: np.ndarray                 # mono, float64, digital full scale
    fs: int
    mode: str
    label: str                          # human-readable provenance
    channels: int = 1
    bit_depth: str = "unknown"
    source_url: str = ""
    category: str = ""                  # ground-truth label if the dataset provides one
    recording_id: str = ""              # groups segments of one original recording (leakage control)
    notes: list = field(default_factory=list)

    @property
    def duration_s(self):
        return len(self.samples) / self.fs

    def info(self):
        x = self.samples
        return {"Mode": self.mode, "Source": self.label, "Sampling rate (Hz)": self.fs,
                "Duration (s)": round(self.duration_s, 4), "Samples": len(x), "Channels (original)": self.channels,
                "Bit depth / dtype": self.bit_depth, "Peak (full-scale)": round(float(np.max(np.abs(x))), 4),
                "RMS (full-scale)": round(float(np.sqrt(np.mean(x ** 2))), 5)}


def validate_fs(fs):
    try:
        fs = int(fs)
    except (TypeError, ValueError):
        raise AudioError(f"Sampling rate {fs!r} is not a number.")
    if not FS_MIN <= fs <= FS_MAX:
        raise AudioError(f"Sampling rate {fs} Hz is outside the supported range {FS_MIN}-{FS_MAX} Hz.")
    return fs


def _normalise(data):
    x = np.asarray(data)
    kind, bits = x.dtype.kind, x.dtype.itemsize * 8
    if kind == "u":
        return (x.astype(np.float64) - 2 ** (bits - 1)) / 2 ** (bits - 1), f"uint{bits}"
    if kind == "i":
        return x.astype(np.float64) / float(2 ** (bits - 1)), f"int{bits}"
    if kind == "f":
        return x.astype(np.float64), f"float{bits}"
    raise AudioError(f"Unsupported sample type {x.dtype}.")


def clip_from_array(x, fs, mode, label, **kw):
    """Build a validated AudioClip from an in-memory array (used for synthetic and recorded audio)."""
    if mode not in MODES:
        raise AudioError(f"Unknown mode {mode!r}")
    fs = validate_fs(fs)
    x = np.asarray(x, dtype=np.float64)
    ch = x.shape[1] if x.ndim == 2 else 1
    if x.ndim == 2:
        x = x.mean(axis=1)
    if x.ndim != 1 or len(x) < MIN_SAMPLES:
        raise AudioError(f"Recording is empty or too short (need at least {MIN_SAMPLES} samples).")
    if not np.all(np.isfinite(x)):
        raise AudioError("Recording contains NaN/Inf samples and looks corrupted.")
    c = AudioClip(x, fs, mode, label, channels=ch, **kw)
    if float(np.max(np.abs(x))) == 0.0:
        c.notes.append("Recording is digital silence (all zeros); results will not be meaningful.")
    return c


def load_wav_bytes(raw, label="uploaded.wav", mode="uploaded", **kw):
    """Decode WAV bytes. Raises AudioError (never a bare exception) with an actionable message."""
    if raw is None or len(raw) == 0:
        raise AudioError("The file is empty (0 bytes). Choose a valid WAV file.")
    try:
        fs, data = wavfile.read(io.BytesIO(raw))
    except Exception as e:
        data = None
        err = str(e)
        try:                                   # optional fallback for formats scipy cannot read
            import soundfile as sf
            data, fs = sf.read(io.BytesIO(raw), always_2d=False)
        except ImportError:
            raise AudioError(f"Could not read this file as WAV ({err}). It may be corrupted or use an unsupported "
                             "encoding (e.g. ADPCM/MP3). Convert it to 16-bit PCM WAV, or install the optional "
                             "'soundfile' package for more formats.")
        except Exception as e2:
            raise AudioError(f"Could not decode audio file: {err}; fallback also failed: {e2}")
    x, depth = _normalise(data)
    return clip_from_array(x, fs, mode, label, bit_depth=depth, **kw)


def load_wav_path(path, mode="downloaded", label=None, **kw):
    from pathlib import Path
    p = Path(path)
    if not p.exists():
        raise AudioError(f"File not found: {p}")
    return load_wav_bytes(p.read_bytes(), label or p.name, mode, **kw)


def segment(clip, start_s=0.0, length_s=None, max_samples=None):
    """Return a mono slice of the clip (the denoising pipeline's pure-Python LMS is slow on long input)."""
    i0 = int(max(0.0, start_s) * clip.fs)
    i1 = len(clip.samples) if length_s is None else min(len(clip.samples), i0 + int(length_s * clip.fs))
    if max_samples:
        i1 = min(i1, i0 + int(max_samples))
    if i1 - i0 < MIN_SAMPLES:
        raise AudioError("Selected segment is too short.")
    return clip.samples[i0:i1].copy()


def to_wav_bytes(x, fs, normalise=True):
    """16-bit PCM WAV bytes for browser playback (peak-normalised to 0.9 if requested)."""
    x = np.asarray(x, dtype=np.float64)
    if normalise and np.max(np.abs(x)) > 0:
        x = 0.9 * x / np.max(np.abs(x))
    buf = io.BytesIO()
    wavfile.write(buf, int(fs), (np.clip(x, -1, 1) * 32767).astype(np.int16))
    return buf.getvalue()


def playback_bytes(x, fs, max_fs=48000):
    """WAV bytes safe for browsers. Returns (bytes, note). Recordings above 48 kHz are band-limited to 24 kHz
    for playback only; the analysis always uses the original sampling rate."""
    note = "Playback is peak-normalised."
    if fs > max_fs:
        from math import gcd
        g = gcd(int(fs), max_fs)
        x = resample_poly(x, max_fs // g, int(fs) // g)
        fs = max_fs
        note += f" Resampled to {max_fs} Hz for playback (content above {max_fs // 2} Hz is not audible here)."
    return to_wav_bytes(x, fs), note


def record_from_device(seconds=3.0, fs=44100):
    """Optional: record from the default input device. Requires the optional 'sounddevice' package.
    A laptop microphone records AIRBORNE sound; it is not a calibrated underwater hydrophone."""
    try:
        import sounddevice as sd
    except Exception as e:
        raise AudioError(f"Live recording needs the optional 'sounddevice' package and an input device ({e}). "
                         "Use WAV upload instead.")
    try:
        data = sd.rec(int(seconds * fs), samplerate=fs, channels=1, dtype="float64")
        sd.wait()
    except Exception as e:
        raise AudioError(f"Could not open an audio input device: {e}")
    return clip_from_array(data[:, 0], fs, "recorded", "Local microphone (airborne sound, not a hydrophone)")
